fn read_head(name: &str) -> FrameSet {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/wcsconv/inputs")
        .join(name);
    let text = std::fs::read_to_string(&path).unwrap();
    let mut fc = FitsChan::from_header(&text).unwrap();
    match fc.read().unwrap().unwrap() {
        AnyObject::FrameSet(fs) => fs,
        other => panic!("{name}: expected a FrameSet, got {other:?}"),
    }
}

/// The Frame a construction case id names, built as the probe builds it.
fn frame(id: &str) -> Box<dyn Frame> {
    match id {
        "basic2" => Box::new(BasicFrameBuilder::new(2).build().unwrap()),
        "basic2_perm" => {
            let mut f = BasicFrameBuilder::new(2).build().unwrap();
            f.set_domain("PIX");
            f.perm_axes(&[2, 1]).unwrap();
            Box::new(f)
        }
        "basic3" => {
            let mut f = BasicFrameBuilder::new(3).build().unwrap();
            f.set_domain("CUBE");
            Box::new(f)
        }
        "sky" => Box::new(SkyFrame::unset_system()),
        "sky_spec" => Box::new(CmpFrame::new(
            Box::new(SkyFrame::unset_system()),
            Box::new(SpecFrame::unset_system()),
        )),
        "car1" => Box::new(read_head("car1.head")),
        "plot_of_sky" => Box::new(
            Plot::new(
                &SkyFrame::unset_system(),
                [0.1, 0.1, 0.9, 0.9],
                [0.0, 0.0, 1.0, 1.0],
            )
            .unwrap(),
        ),
        _ => panic!("unknown frame id {id}"),
    }
}

fn build(case: &construct::Construct) -> Plot {
    if case.id == "null" {
        Plot::default_frame(case.graphbox, case.basebox).unwrap()
    } else {
        Plot::new(frame(case.id).as_ref(), case.graphbox, case.basebox).unwrap()
    }
}

#[test]
fn plot_construction_matches_the_c_library() {
    let mut failures = Vec::new();
    for (n, case) in construct::CONSTRUCT_CASES.iter().enumerate() {
        let plot = build(case);
        let fs = plot.frameset();
        let domains: Vec<String> = (1..=fs.nframe())
            .map(|i| fs.frame(FrameRef::Index(i)).unwrap().domain().to_string())
            .collect();
        let graphics = fs.frame(FrameRef::Index(1)).unwrap();
        let got = (
            fs.nframe(),
            fs.base_index(),
            fs.current_index(),
            domains,
            plot.graphics_box(),
            plot.reversed(),
            [
                graphics.direction(1).unwrap(),
                graphics.direction(2).unwrap(),
            ],
        );
        let want = (
            case.nframe,
            case.base,
            case.current,
            case.domains
                .iter()
                .map(|s| s.to_string())
                .collect::<Vec<_>>(),
            case.bounds,
            case.reversed,
            case.directions,
        );
        if got != want {
            failures.push(format!(
                "case {n} ({}): got {got:?}, C gives {want:?}",
                case.id
            ));
            continue;
        }
        for (p, g) in case.graphics.iter().enumerate() {
            let fwd = plot
                .transform(&starlink_ast::coords::PointSet::from_rows([g]), true)
                .unwrap();
            let fwd = fwd.point(0).to_vec();
            if !crate::common::c_values_eq(&fwd, case.forward[p]) {
                failures.push(format!(
                    "case {n} ({}) point {p}: forward {fwd:?}, C gives {:?}",
                    case.id, case.forward[p]
                ));
                continue;
            }
            let back = plot
                .transform(
                    &starlink_ast::coords::PointSet::from_rows([case.forward[p]]),
                    false,
                )
                .unwrap();
            let back = back.point(0).to_vec();
            if !crate::common::c_values_eq(&back, &case.inverse[p]) {
                failures.push(format!(
                    "case {n} ({}) point {p}: inverse {back:?}, C gives {:?}",
                    case.id, case.inverse[p]
                ));
            }
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn plot_rejects_a_bad_box() {
    let frame = BasicFrameBuilder::new(2).build().unwrap();
    for (graphbox, basebox) in construct::BAD_BOX_CASES {
        let err = Plot::new(&frame, *graphbox, *basebox).unwrap_err();
        assert_eq!(err.code(), ErrorCode::Badbx, "{graphbox:?} {basebox:?}");
    }
}

#[test]
fn a_one_dimensional_base_frame_is_rejected() {
    let frame = BasicFrameBuilder::new(1).build().unwrap();
    let err = Plot::new(&frame, [0.1, 0.1, 0.9, 0.9], [0.0, 0.0, 1.0, 1.0]).unwrap_err();
    assert_eq!(err.code(), ErrorCode::Naxin);
}

/// A Plot is a FrameSet to code that treats FrameSets specially: finding a
/// sky Frame in it searches its Frames, as it does in C.
#[test]
fn a_plot_is_searched_as_a_frameset() {
    use starlink_ast::frames::FrameSearch;
    let case = construct::CONSTRUCT_CASES
        .iter()
        .find(|c| c.id == "car1")
        .unwrap();
    let mut plot = build(case);
    let template = SkyFrame::unset_system();
    let found = plot.find_frame_template(&template, "").unwrap();
    assert!(found.is_some(), "a sky Frame is found in the Plot");
    assert!(Frame::as_frameset(&plot).is_some());
}

/// The names of the methods declared at the top level of the block that
/// starts at `header` in `text`.
fn method_names(text: &str, header: &str) -> std::collections::BTreeSet<String> {
    let start = text
        .find(header)
        .unwrap_or_else(|| panic!("{header} not found"));
    let mut depth = 0_i32;
    let mut names = std::collections::BTreeSet::new();
    let mut in_comment_line;
    for line in text[start..].lines() {
        in_comment_line = line.trim_start().starts_with("//");
        if depth == 1 && !in_comment_line {
            if let Some(rest) = line.trim_start().strip_prefix("fn ") {
                let name: String = rest
                    .chars()
                    .take_while(|c| c.is_alphanumeric() || *c == '_')
                    .collect();
                names.insert(name);
            }
        }
        if !in_comment_line {
            depth += line.matches('{').count() as i32 - line.matches('}').count() as i32;
            if depth == 0 && line.contains('}') {
                break;
            }
        }
    }
    names
}

/// Every Frame and Mapping method has its forwarding in the generated
/// `plot/forward.rs`; rerun `tools/gen_plot_forward.py` when this fails.
#[test]
fn plot_forwards_the_frameset_methods_c_inherits() {
    let src = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("src");
    let read = |p: &str| std::fs::read_to_string(src.join(p)).unwrap();
    let forward = read("plot/forward.rs");
    // Methods the trait restricts to Sized implementors keep their default.
    let sized_only = ["match_axes"];
    // Methods FrameSet does not override in C keep the trait default, which
    // transforms through the Plot itself (INHERIT_MAPPING in the generator).
    let inherited = [
        "tran1",
        "tran2",
        "transform_into_nan",
        "linear_approx",
        "quad_approx",
        "tran_grid",
        "map_box",
    ];
    for (trait_file, header, impl_header) in [
        ("frames/mod.rs", "pub trait Frame: ", "impl Frame for Plot"),
        (
            "mappings/mod.rs",
            "pub trait Mapping: ",
            "impl Mapping for Plot",
        ),
    ] {
        let mut want = method_names(&read(trait_file), header);
        want.retain(|n| !sized_only.contains(&n.as_str()) && !inherited.contains(&n.as_str()));
        let got = method_names(&forward, impl_header);
        assert_eq!(got, want, "{impl_header}: rerun tools/gen_plot_forward.py");
    }
}

/// The Plot an attributes scenario id names, built as the probe builds it.
fn attrs_plot(id: &str) -> Plot {
    let g = [0.1, 0.1, 0.9, 0.9];
    let basic = || BasicFrameBuilder::new(2).build().unwrap();
    let sky = |system: Option<starlink_ast::frames::SkySystem>| {
        let mut f = SkyFrame::unset_system();
        if let Some(s) = system {
            f.set_system(s);
        }
        f
    };
    let sky_box = [0.0, -0.5, 1.0, 0.5];
    match id {
        "basic2" => Plot::new(&basic(), g, [0.0, 0.0, 100.0, 50.0]),
        "basic2_pos" => Plot::new(&basic(), g, [1.0, 2.0, 100.0, 50.0]),
        "basic2_neg" => Plot::new(&basic(), g, [-100.0, -50.0, -1.0, -2.0]),
        "basic2_rev" => Plot::new(&basic(), [0.9, 0.1, 0.1, 0.9], [1.0, 2.0, 100.0, 50.0]),
        "sky" => Plot::new(&sky(None), g, sky_box),
        "sky_gal" => Plot::new(
            &sky(Some(starlink_ast::frames::SkySystem::Galactic)),
            g,
            sky_box,
        ),
        "sky_azel" => Plot::new(
            &sky(Some(starlink_ast::frames::SkySystem::Azel)),
            g,
            sky_box,
        ),
        "sky_spec" => Plot::new(
            &CmpFrame::new(
                Box::new(SpecFrame::unset_system()),
                Box::new(SkyFrame::unset_system()),
            ),
            g,
            [1.0, 1.0, 2.0, 2.0],
        ),
        "car1" => Plot::new(&read_head("car1.head"), g, [0.0, 0.0, 2962.0, 562.0]),
        _ => panic!("unknown frame id {id}"),
    }
    .unwrap()
}

/// An attribute name as C writes it, split into its lower-case name and
/// its axis, if any.
fn split_name(name: &str) -> (String, Option<usize>) {
    match name.split_once('(') {
        Some((n, rest)) => (
            n.to_lowercase(),
            Some(rest.trim_end_matches(')').parse().unwrap()),
        ),
        None => (name.to_lowercase(), None),
    }
}

fn edge_named(value: &str) -> Edge {
    match value.chars().next().unwrap().to_ascii_lowercase() {
        'l' => Edge::Left,
        't' => Edge::Top,
        'r' => Edge::Right,
        _ => Edge::Bottom,
    }
}

/// Apply one `Name(axis)=value` setting through the typed setter.
fn set_attr(plot: &mut Plot, setting: &str) -> AstResult<()> {
    let (name, value) = setting.split_once('=').unwrap();
    let (name, axis) = split_name(name);
    let flag = || value.parse::<i32>().unwrap() != 0;
    let num = || value.parse::<f64>().unwrap();
    let int = || value.parse::<i32>().unwrap();
    match (name.as_str(), axis) {
        ("tol", None) => plot.set_tol(num()),
        ("grid", None) => plot.set_grid(flag()),
        ("tickall", None) => plot.set_tick_all(flag()),
        ("forceexterior", None) => plot.set_force_exterior(flag()),
        ("invisible", None) => plot.set_invisible(flag()),
        ("border", None) => plot.set_border(flag()),
        ("clipop", None) => plot.set_clip_op(flag()),
        ("clip", None) => plot.set_clip(int())?,
        ("drawtitle", None) => plot.set_draw_title(flag()),
        ("escape", None) => plot.set_escape(flag()),
        ("titlegap", None) => plot.set_title_gap(num()),
        ("labelling", None) => plot.set_labelling(if value.starts_with("int") {
            Labelling::Interior
        } else {
            Labelling::Exterior
        }),
        ("textgaptype", None) => plot.set_text_gap_type(if value == "plot" {
            TextGapType::Plot
        } else {
            TextGapType::Box
        }),
        ("drawaxes", Some(a)) => plot.set_draw_axes(a, flag())?,
        ("abbrev", Some(a)) => plot.set_abbreviate(a, flag())?,
        ("labelat", Some(a)) => plot.set_label_at(a, num())?,
        ("centre", Some(a)) => plot.set_tick_centre(a, num())?,
        ("gap", Some(a)) => plot.set_tick_gap(a, num())?,
        ("loggap", Some(a)) => plot.set_log_gap(a, num())?,
        ("numlabgap", Some(a)) => plot.set_num_lab_gap(a, num())?,
        ("textlabgap", Some(a)) => plot.set_text_lab_gap(a, num())?,
        ("labelup", Some(a)) => plot.set_label_up(a, flag())?,
        ("logplot", Some(a)) => plot.set_log_plot(a, flag())?,
        ("logticks", Some(a)) => plot.set_log_ticks(a, flag())?,
        ("loglabel", Some(a)) => plot.set_log_label(a, flag())?,
        ("numlab", Some(a)) => plot.set_num_lab(a, flag())?,
        ("mintick", Some(a)) => plot.set_min_tick(a, int())?,
        ("textlab", Some(a)) => plot.set_text_lab(a, flag())?,
        ("labelunits", Some(a)) => plot.set_label_units(a, flag())?,
        ("majticklen", Some(a)) => plot.set_maj_tick_len(a, num())?,
        ("minticklen", Some(a)) => plot.set_min_tick_len(a, num())?,
        ("edge", Some(a)) => plot.set_edge(a, edge_named(value))?,
        _ => panic!("no setter for {setting}"),
    }
    Ok(())
}

/// Clear one attribute through the typed clearer.
fn clear_attr(plot: &mut Plot, name: &str) -> AstResult<()> {
    match split_name(name) {
        (n, None) if n == "grid" => plot.clear_grid(),
        (n, Some(a)) if n == "gap" => plot.clear_tick_gap(a)?,
        (n, Some(a)) if n == "edge" => plot.clear_edge(a)?,
        (n, Some(a)) if n == "logplot" => plot.clear_log_plot(a)?,
        (n, a) => panic!("no clearer for {n} {a:?}"),
    }
    Ok(())
}

/// An attribute's set state and value, read through the typed accessors.
fn query_attr(plot: &Plot, name: &str) -> (bool, attrs::Value) {
    use attrs::Value::{D, I, S};
    let i = |b: bool| I(b as i32);
    match split_name(name) {
        (n, None) => match n.as_str() {
            "tol" => (plot.test_tol(), D(plot.tol())),
            "grid" => (plot.test_grid(), i(plot.grid())),
            "tickall" => (plot.test_tick_all(), i(plot.tick_all())),
            "forceexterior" => (plot.test_force_exterior(), i(plot.force_exterior())),
            "invisible" => (plot.test_invisible(), i(plot.invisible())),
            "border" => (plot.test_border(), i(plot.border())),
            "clipop" => (plot.test_clip_op(), i(plot.clip_op())),
            "clip" => (plot.test_clip(), I(plot.clip())),
            "drawtitle" => (plot.test_draw_title(), i(plot.draw_title())),
            "escape" => (plot.test_escape(), i(plot.escape())),
            "titlegap" => (plot.test_title_gap(), D(plot.title_gap())),
            "labelling" => (plot.test_labelling(), S(plot.labelling().name())),
            "textgaptype" => (plot.test_text_gap_type(), S(plot.text_gap_type().name())),
            _ => panic!("no getter for {name}"),
        },
        (n, Some(a)) => match n.as_str() {
            "drawaxes" => (
                plot.test_draw_axes(a).unwrap(),
                i(plot.draw_axes(a).unwrap()),
            ),
            "abbrev" => (
                plot.test_abbreviate(a).unwrap(),
                i(plot.abbreviate(a).unwrap()),
            ),
            "labelat" => (plot.test_label_at(a).unwrap(), D(plot.label_at(a).unwrap())),
            "centre" => (
                plot.test_tick_centre(a).unwrap(),
                D(plot.tick_centre(a).unwrap()),
            ),
            "gap" => (plot.test_tick_gap(a).unwrap(), D(plot.tick_gap(a).unwrap())),
            "loggap" => (plot.test_log_gap(a).unwrap(), D(plot.log_gap(a).unwrap())),
            "numlabgap" => (
                plot.test_num_lab_gap(a).unwrap(),
                D(plot.num_lab_gap(a).unwrap()),
            ),
            "textlabgap" => (
                plot.test_text_lab_gap(a).unwrap(),
                D(plot.text_lab_gap(a).unwrap()),
            ),
            "labelup" => (plot.test_label_up(a).unwrap(), i(plot.label_up(a).unwrap())),
            "logplot" => (plot.test_log_plot(a).unwrap(), i(plot.log_plot(a).unwrap())),
            "logticks" => (
                plot.test_log_ticks(a).unwrap(),
                i(plot.log_ticks(a).unwrap()),
            ),
            "loglabel" => (
                plot.test_log_label(a).unwrap(),
                i(plot.log_label(a).unwrap()),
            ),
            "numlab" => (plot.test_num_lab(a).unwrap(), i(plot.num_lab(a).unwrap())),
            "mintick" => (plot.test_min_tick(a).unwrap(), I(plot.min_tick(a).unwrap())),
            "textlab" => (plot.test_text_lab(a).unwrap(), i(plot.text_lab(a).unwrap())),
            "labelunits" => (
                plot.test_label_units(a).unwrap(),
                i(plot.label_units(a).unwrap()),
            ),
            "majticklen" => (
                plot.test_maj_tick_len(a).unwrap(),
                D(plot.maj_tick_len(a).unwrap()),
            ),
            "minticklen" => (
                plot.test_min_tick_len(a).unwrap(),
                D(plot.min_tick_len(a).unwrap()),
            ),
            "edge" => (plot.test_edge(a).unwrap(), S(plot.edge(a).unwrap().name())),
            _ => panic!("no getter for {name}"),
        },
    }
}

/// Attributes whose set state on a new Plot C leaves undefined, as
/// `(attribute, reason)`; their set state is not compared unless the
/// scenario sets them, and their value still is.
const UNINITIALISED_SET_STATE_EXCLUDED: &[(&str, &str)] = &[(
    "ForceExterior",
    "C's astInitPlot never initialises forceexterior, so a new Plot reads as \
     having it set to whatever the allocator left (0 here); the port starts \
     it unset (c-library-quirks.md)",
)];

fn set_state_excluded(name: &str, setting: &str) -> bool {
    UNINITIALISED_SET_STATE_EXCLUDED
        .iter()
        .any(|(attr, _)| *attr == name && !setting.contains(attr))
}

/// C still reports each excluded attribute as set on a new Plot, so the
/// exclusion still describes C.
#[test]
fn uninitialised_set_states_still_differ_from_c() {
    for (attr, reason) in UNINITIALISED_SET_STATE_EXCLUDED {
        let sc = &attrs::SCENARIOS[0];
        let want = sc
            .attrs
            .unwrap()
            .iter()
            .find(|(n, _, _)| n == attr)
            .unwrap()
            .1;
        let (set, _) = query_attr(&attrs_plot(sc.id), attr);
        assert_ne!(
            Some(set),
            want,
            "{attr} now matches C; remove it ({reason})"
        );
    }
}

#[test]
fn plot_attributes_match_the_c_library() {
    let mut failures = Vec::new();
    for (n, sc) in attrs::SCENARIOS.iter().enumerate() {
        let mut plot = attrs_plot(sc.id);
        let mut result = Ok(());
        for setting in sc.set.split(',').filter(|s| !s.is_empty()) {
            result = result.and_then(|_| set_attr(&mut plot, setting));
        }
        for name in sc.clear.split(',').filter(|s| !s.is_empty()) {
            result = result.and_then(|_| clear_attr(&mut plot, name));
        }
        let what = format!(
            "scenario {n} ({} \"{}\" clear \"{}\")",
            sc.id, sc.set, sc.clear
        );
        let Some(want) = sc.attrs else {
            if result.is_ok() {
                failures.push(format!("{what}: C rejects it, the port accepts it"));
            }
            continue;
        };
        if let Err(e) = result {
            failures.push(format!("{what}: {e}"));
            continue;
        }
        for (name, want_set, want_value) in want {
            let (set, value) = query_attr(&plot, name);
            let value_ok = match (&value, want_value) {
                (attrs::Value::D(g), attrs::Value::D(w)) => crate::common::c_value_eq(*g, *w),
                (g, w) => g == w,
            };
            let set_ok = set_state_excluded(name, sc.set) || want_set.is_none_or(|w| w == set);
            if !set_ok || !value_ok {
                failures.push(format!(
                    "{what}: {name} got ({set}, {value:?}), C gives ({want_set:?}, {want_value:?})"
                ));
            }
        }
        for (k, g) in [[0.15, 0.2], [0.5, 0.5], [0.85, 0.8]]
            .iter()
            .enumerate()
            .take(sc.forward.len())
        {
            let out = plot
                .transform(&starlink_ast::coords::PointSet::from_rows([g]), true)
                .unwrap();
            let out = out.point(0).to_vec();
            if !crate::common::c_values_eq(&out, &sc.forward[k]) {
                failures.push(format!(
                    "{what}: point {k} goes to {out:?}, C gives {:?}",
                    sc.forward[k]
                ));
            }
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// A style attribute name as C writes it, `Colour(Axes)`, split into its
/// lower-case attribute name and its element, `None` for a name C does
/// not know.
fn split_style(name: &str) -> (String, Option<PlotElement>) {
    let (attr, element) = name.split_once('(').unwrap();
    let element = element.trim_end_matches(')');
    let found = PlotElement::ALL
        .into_iter()
        .find(|e| e.name().eq_ignore_ascii_case(element));
    (attr.to_lowercase(), found)
}

fn set_style_attr(plot: &mut Plot, setting: &str) -> AstResult<()> {
    let (name, value) = setting.split_once('=').unwrap();
    let (attr, element) = split_style(name);
    let Some(element) = element else {
        return Err(starlink_ast::error::AstError::new(
            ErrorCode::Badat,
            format!("unknown element in {name}"),
        ));
    };
    let int = || value.trim().parse::<i32>().unwrap();
    let real = || value.trim().parse::<f64>().unwrap();
    match attr.as_str() {
        "style" => plot.set_style(element, int()),
        "font" => plot.set_font(element, int()),
        "colour" => plot.set_colour(element, int()),
        "width" => return plot.set_width(element, real()),
        "size" => return plot.set_size(element, real()),
        _ => panic!("unknown style attribute {attr}"),
    }
    Ok(())
}

fn clear_style_attr(plot: &mut Plot, name: &str) {
    let (attr, element) = split_style(name);
    let element = element.unwrap();
    match attr.as_str() {
        "style" => plot.clear_style(element),
        "font" => plot.clear_font(element),
        "colour" => plot.clear_colour(element),
        "width" => plot.clear_width(element),
        "size" => plot.clear_size(element),
        _ => panic!("unknown style attribute {attr}"),
    }
}

fn query_style_attr(plot: &Plot, attr: &str, element: PlotElement) -> (bool, attrs::Value) {
    match attr {
        "Style" => (
            plot.test_style(element),
            attrs::Value::I(plot.style(element)),
        ),
        "Font" => (plot.test_font(element), attrs::Value::I(plot.font(element))),
        "Colour" => (
            plot.test_colour(element),
            attrs::Value::I(plot.colour(element)),
        ),
        "Width" => (
            plot.test_width(element),
            attrs::Value::D(plot.width(element)),
        ),
        "Size" => (plot.test_size(element), attrs::Value::D(plot.size(element))),
        _ => panic!("unknown style attribute {attr}"),
    }
}

#[test]
fn plot_styles_match_the_c_library() {
    let mut failures = Vec::new();
    for (n, sc) in attrs::STYLE_SCENARIOS.iter().enumerate() {
        let mut plot = attrs_plot("basic2");
        let mut result = Ok(());
        for setting in sc.set.split(',').filter(|s| !s.is_empty()) {
            result = result.and_then(|_| set_style_attr(&mut plot, setting));
        }
        if result.is_ok() {
            for name in sc.clear.split(',').filter(|s| !s.is_empty()) {
                clear_style_attr(&mut plot, name);
            }
        }
        let what = format!("style scenario {n} (\"{}\" clear \"{}\")", sc.set, sc.clear);
        let Some(want) = sc.attrs else {
            if result.is_ok() {
                failures.push(format!("{what}: C rejects it, the port accepts it"));
            }
            continue;
        };
        if let Err(e) = result {
            failures.push(format!("{what}: {e}"));
            continue;
        }
        for (attr, element, want_set, want_value) in want {
            let element = split_style(&format!("{attr}({element})")).1.unwrap();
            let (set, value) = query_style_attr(&plot, attr, element);
            if set != *want_set || value != *want_value {
                failures.push(format!(
                    "{what}: {attr}({}) got ({set}, {value:?}), C gives ({want_set}, {want_value:?})",
                    element.name()
                ));
            }
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
